    fn parse_transaction(&self, transaction: impl Into<crate::Value>, currency: Option<&crate::types::Currency>) -> Value {
        let transaction: Value = transaction.into();
        //
        //     {
        //         "id":"fbf7d0d1-2629-4ad8-9def-7a1dba423362",
        //         "status":"TRANSACTION_STATUS_CONFIRMED",
        //         "type":"TRANSACTION_TYPE_DEPOSIT",
        //         "senderAddress":"",
        //         "recipientAddress":"0x3c46fa2e3f9023bc4897828ed173f8ecb3a554bc",
        //         "amount":"200.000000000000000000",
        //         "transactionFee":"0.000000000000000000",
        //         "timestamp":1635893208404,
        //         "transactionHash":"0x28bad3b74a042df13d64ddfbca855566a51bf7f190b8cd565c236a18d5cd493f#42",
        //         "blockHeight":13540262,
        //         "currency":"0c3a106d-bde3-4c13-a26e-3fd2394529e5",
        //         "memo":null,
        //         "paymentProvider":"a8d6d1cb-f84a-4e9d-aa82-c6a08b356ee1",
        //         "requiresCode":false
        //     }
        //
        let id: Option<String> = self.safe_string_k_opt(&transaction, "id", &[]);
        let timestamp: Option<i64> = self.safe_integer_k(&transaction, "timestamp", &[]).as_i64();
        let currencyId: Option<String> = self.safe_string_k_opt(&transaction, "currency", &[]);
        let code: Option<String> = self.safe_currency_code(currencyId.as_deref(), currency);
        let status: Option<String> = self.parse_transaction_status(self.safe_string_k(&transaction, "status", &[]).as_str());
        let amount: Option<f64> = self.safe_number_k(&transaction, "amount", &[]).as_f64();
        let addressFrom: Option<String> = self.safe_string_k_opt(&transaction, "senderAddress", &[]);
        let addressTo: Option<String> = self.safe_string_k_opt(&transaction, "recipientAddress", &[]);
        let txid: Option<String> = self.safe_string_k_opt(&transaction, "transactionHash", &[]);
        let tagTo: Option<String> = self.safe_string_k_opt(&transaction, "memo", &[]);
        let mut fee: indexmap::IndexMap<String, Value> = ({
            let mut m = indexmap::IndexMap::new();
                m.insert("currency".to_string(), Value::Null);
                m.insert("cost".to_string(), Value::Null);
                m.insert("rate".to_string(), Value::Null);
            m
        });
        let feeCost: Option<f64> = self.safe_number_k(&transaction, "transactionFee", &[]).as_f64();
        if (feeCost.is_some()) {
            fee.insert("cost".into(), Value::from(feeCost));
            fee.insert("currency".into(), Value::from(code.as_deref()));
        }
        let type_var: Option<String> = self.parse_transaction_type(self.safe_string_k(&transaction, "type", &[]).as_str());
        return Value::Map({
    let mut m = indexmap::IndexMap::new();
        m.insert("info".to_string(), transaction);
        m.insert("id".to_string(), id.map(Value::from).unwrap_or(Value::Null));
        m.insert("txid".to_string(), txid.map(Value::from).unwrap_or(Value::Null));
        m.insert("timestamp".to_string(), Value::from(timestamp));
        m.insert("datetime".to_string(), self.iso8601(timestamp));
        m.insert("network".to_string(), Value::Null);
        m.insert("addressFrom".to_string(), addressFrom.map(Value::from).unwrap_or(Value::Null));
        m.insert("addressTo".to_string(), Value::from(addressTo.as_deref()));
        m.insert("address".to_string(), addressTo.map(Value::from).unwrap_or(Value::Null));
        m.insert("tagFrom".to_string(), Value::Null);
        m.insert("tagTo".to_string(), Value::from(tagTo.as_deref()));
        m.insert("tag".to_string(), tagTo.map(Value::from).unwrap_or(Value::Null));
        m.insert("type".to_string(), type_var.map(Value::from).unwrap_or(Value::Null));
        m.insert("amount".to_string(), Value::from(amount));
        m.insert("currency".to_string(), code.map(Value::from).unwrap_or(Value::Null));
        m.insert("status".to_string(), status.map(Value::from).unwrap_or(Value::Null));
        m.insert("updated".to_string(), Value::Null);
        m.insert("comment".to_string(), Value::Null);
        m.insert("internal".to_string(), Value::Null);
        m.insert("fee".to_string(), Value::Map(fee));
    m
});

    Value::Null
}
    fn sign(&mut self, path: &str, optional_args: &[Value]) -> Value {
        let mut api = get_arg(optional_args, 0, Value::from(vec![Value::Str("public".into())]));
        let method = get_arg(optional_args, 1, Value::Str("GET".into()));
        let params = get_arg(optional_args, 2, Value::Map({
    let m = indexmap::IndexMap::new();
    m
}));
        let __api_empty = Vec::new();
        let api = api.as_array().unwrap_or(&__api_empty);
        let apiName: Option<String> = api.get(0).and_then(Value::as_str).map(str::to_owned);
        let mut requestHeaders: Option<crate::value::Dict> = None;
        let mut requestBody: Option<String> = None;
        let request: String = format!("{}{}", Value::Str(format!("{}{}", Value::Str(format!("{}{}", "/", self.version).into()), "/").into()), self.implode_params(Value::from(path), &params));
        let mut requestString: String = request.clone();
        let query: crate::value::Dict = self.omit_t(params, self.extract_params(Value::from(path)), &[]);
        let urlencodedQuery: String = self.urlencode(&query, &[]);
        if (method.as_str() == Some("GET")) {
            if (urlencodedQuery != "") {
                requestString.push_str(&format!("{}{}", "?", urlencodedQuery));
            }
        }
        if (apiName.as_deref() == Some("private")) {
            self.check_required_credentials(&[]);
            let auth: String = format!("{}{}", Value::Str(format!("{}{}", method, request).into()), urlencodedQuery);
            let signature: String = self.hmac(self.encode(Value::from(auth)), self.encode(&self.secret), "sha512", &[]);
            requestHeaders = Some(crate::value::Dict::new({
                let mut m = indexmap::IndexMap::new();
                    m.insert("X-LA-APIKEY".to_string(), self.apiKey.clone());
                    m.insert("X-LA-SIGNATURE".to_string(), Value::from(signature));
                    m.insert("X-LA-DIGEST".to_string(), Value::Str("HMAC-SHA512".into()));
                m
            }));
            if (method.as_str() == Some("POST")) {
                if let Some(__d) = &mut requestHeaders { std::sync::Arc::make_mut(__d).insert("Content-Type".to_string(), Value::Str("application/json".into())); }
                requestBody = json_stringify(&query).as_str().map(str::to_owned);
            }
        }
        let apiUrl: Option<String> = self.safe_string_k_opt(self.urls.get("api").cloned().unwrap_or(Value::Null), "rest", &[]);
        if (apiUrl.is_none()) {
            panic!("{}", crate::exchange_errors::exchange_error(format!("{}{}", self.id, " sign() has no API URL for this endpoint")));
        }
        let url: String = format!("{}{}", apiUrl.as_deref().unwrap_or("null"), requestString);
        return Value::Map({
    let mut m = indexmap::IndexMap::new();
        m.insert("url".to_string(), Value::from(url));
        m.insert("method".to_string(), method);
        m.insert("body".to_string(), requestBody.map(Value::from).unwrap_or(Value::Null));
        m.insert("headers".to_string(), requestHeaders.map_or(Value::Null, Value::Dict));
    m
});

    Value::Null
}
    fn handle_errors(&mut self, mut code: Value, mut reason: Value, mut url: Value, mut method: Value, mut headers: Value, mut body: Value, mut response: Value, mut requestHeaders: Value, mut requestBody: Value) -> Value {
        if (response == Value::Null) {
            return Value::Null;
        }
        //
        // {"result":false,"message":"invalid API key, signature or digest","error":"BAD_REQUEST","status":"FAILURE"}
        // {"result":false,"message":"request expired or bad <timeAlive>/<timestamp> format","error":"BAD_REQUEST","status":"FAILURE"}
        // {"message":"Internal Server Error","error":"INTERNAL_ERROR","status":"FAILURE"}
        // {"result":false,"message":"Internal error","error":"For input string: \"NaN\"","status":"FAILURE"}
        //
        let message: Option<String> = self.safe_string_k_opt(&response, "message", &[]);
        let feedback: String = format!("{}{}", Value::Str(format!("{}{}", self.id, " ").into()), body);
        if (message.is_some()) {
            self.throw_exactly_matched_exception(self.exceptions.at("exact"), Value::from(message.as_deref()), feedback.as_str());
            self.throw_broadly_matched_exception(self.exceptions.at("broad"), &message, feedback.as_str());
        }
        let error: Option<String> = self.safe_string_k_opt(response, "error", &[]);
        if (error.is_some()) {
            self.throw_exactly_matched_exception(self.exceptions.at("exact"), &error, feedback.as_str());
            self.throw_broadly_matched_exception(self.exceptions.at("broad"), body, feedback.as_str());
            panic!("{}", crate::exchange_errors::exchange_error(feedback));
        }
        return Value::Null;

    Value::Null
}
